#!/usr/bin/env bash
set -euo pipefail
R="${TRACK2_ROOT:-/root/autodl-tmp/IROS_WAM_2.0 challenge}";P="${TRACK2_GO1_PYTHON:-/root/miniconda3/envs/go1/bin/python}";J="$R/artifacts/strict_track2_joint_augmentation_20260810";RUN="$J/v256_v254_delta_regime_long128_seed1458_20260819";V='track2-v254-delta-regime-terminal';TOKEN='local-dev-token'
svc(){ cd "$R";exec env PYTHONPATH="$R/pipeline" WAM_MODEL_VERSION="$V" WAM_BEARER_TOKEN="$TOKEN" WAM_BACKEND='v254-delta-regime-terminal' WAM_CHECKPOINT_DIR="$J/v209_v202_v208_public_arm_routed_release" WAM_V216_LIBRARY_INDEX="$J/v214_public_right_knn_action_visual_diagnostic_seed1413/library/public_right_knn.npz" WAM_DEVICE=cuda WAM_PORT=8005 WAM_NATIVE_BATCH_ENABLED=1 WAM_NATIVE_BATCH_MICRO_SIZE=8 WAM_RELEASE_CUDA_CACHE=0 "$P" pipeline/scripts/serve.py >>"$RUN/v254_service.log" 2>&1;}
bridge(){ cd "$R";exec env PYTHONPATH="$R/pipeline" "$P" -m wam_pipeline.rlinf_bridge.server --world-model-url http://127.0.0.1:8005 --token "$TOKEN" --model-version "$V" --host 127.0.0.1 --port 18084 --audit-max-items 1 >>"$RUN/v254_bridge.log" 2>&1;}
waitf(){ for _ in $(seq 1 "$2");do curl -fsS "$1" >/dev/null 2>&1&&return 0;sleep 1;done;return 1;}
case "${1:-start}" in svc)svc;;bridge)bridge;;stop)screen -S wm_v254_bridge -X quit >/dev/null 2>&1||true;screen -S wm_v254_gpu -X quit >/dev/null 2>&1||true;;start)for n in wm_v254_bridge wm_v254_gpu wm_v218_bridge wm_v218_gpu;do screen -S "$n" -X quit >/dev/null 2>&1||true;done;for _ in $(seq 1 30);do ! ss -ltn|grep -qE ':(8005|18084) '&&break;sleep 1;done;screen -dmS wm_v254_gpu bash "$0" svc;waitf http://127.0.0.1:8005/v1/health 120;curl -fsS http://127.0.0.1:8005/v1/health|grep -q "$V";screen -dmS wm_v254_bridge bash "$0" bridge;waitf http://127.0.0.1:18084/health 60;echo V254_SERVICES_READY;;*)exit 2;;esac
